net correlated_join "Ship a ready order with its own account's settings and a courier for its region"

@arc_0: (orders) -purchase-> [ship]
[ship] -shipment-> (shipped)
@arc_2: (settings) -setting->? [ship]
@arc_3: (couriers) -courier-> [ship]
@arc_4: (pauses) -pause->0 [ship]
[ship] -courier-> (couriers)

[ship] handler "ship_order"

@arc_0 predicate cel "status == 'ready'"
@arc_3 predicate cel "available"

@arc_2 correlate cel "token.account == binding.orders[0].account"
@arc_3 correlate cel "token.region == binding.orders[0].region"
@arc_4 correlate cel "token.account == binding.orders[0].account"

marking initial (orders) <- $token_0
marking initial (orders) <- $token_1
marking initial (settings) <- $token_2
marking initial (settings) <- $token_3
marking initial (couriers) <- $token_4
marking initial (couriers) <- $token_5
$token_0: purchase {"account":"A","region":"west","status":"ready"}
$token_1: purchase {"account":"B","region":"east","status":"ready"}
$token_2: setting {"account":"A","carrier":"post"}
$token_3: setting {"account":"B","carrier":"van"}
$token_4: courier {"available":true,"region":"east"}
$token_5: courier {"available":true,"region":"west"}
